targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({ api, event }) {
    var appliedFilters = event.payload.appliedFilters;
    var knowledgeBase = 'All';                                                   
    if (appliedFilters && appliedFilters[0] && appliedFilters[0].values && appliedFilters[0].values[0]) {                                              
    	knowledgeBase = appliedFilters[0].values[0];
    }                                                                                                
    return {                                                                
        propName: "knowledgeBase",
        value: knowledgeBase
    };
}  )

